REVOKE ALL ON SCHEMA public FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO v_scheduling_runtime;
DO $$ BEGIN EXECUTE format('REVOKE CONNECT,CREATE,TEMPORARY ON DATABASE %I FROM PUBLIC',current_database()); END $$;
DO $$ BEGIN EXECUTE format('GRANT CONNECT ON DATABASE %I TO v_scheduling_runtime,v_scheduling_migration',current_database()); END $$;
GRANT SELECT,INSERT ON "scheduling_request","scheduling_request_enrollment","scheduling_request_group","scheduling_request_resource","scheduling_request_window","scheduling_rule_version","scheduling_request_rule","scheduling_operation_rule","candidate_lesson","candidate_lesson_participant","recurring_lesson_series","lesson","lesson_participant","scheduling_operation","reservation_claim","lesson_change","assessment_appointment" TO v_scheduling_runtime;
GRANT UPDATE("status","planning_start","planning_end","submitted_by_user_id","submitted_at","generated_at","confirmed_operation_id","confirmed_at","created_by_user_id") ON "scheduling_request" TO v_scheduling_runtime;
GRANT UPDATE("student_id","enrollment_revision","training_program_version_id","category_code") ON "scheduling_request_enrollment" TO v_scheduling_runtime;
GRANT UPDATE("training_program_version_id","category_code","membership_revision") ON "scheduling_request_group" TO v_scheduling_runtime;
GRANT UPDATE("eligibility_revision") ON "scheduling_request_resource" TO v_scheduling_runtime;
GRANT UPDATE("request_id","request_revision","starts_at","ends_at") ON "scheduling_request_window" TO v_scheduling_runtime;
GRANT UPDATE("rule_id","revision","source_kind","category_code","rule_code","severity","override_policy","scope_kind","scope_resource_id","decision_reason","numeric_limit","unit","effective_from","effective_to","source_reference","verification_status","decided_at","created_by_user_id","decided_by_user_id") ON "scheduling_rule_version" TO v_scheduling_runtime;
GRANT UPDATE("request_id","request_revision","kind","student_id","enrollment_id","group_id","teacher_id","vehicle_id","branch_id","series_id","starts_at","ends_at","category_code") ON "candidate_lesson" TO v_scheduling_runtime;
GRANT UPDATE("student_id","membership_revision") ON "candidate_lesson_participant" TO v_scheduling_runtime;
GRANT UPDATE("kind","frequency","recurrence_interval","weekdays","local_start_time","duration_minutes","time_zone","starts_on","ends_on","occurrence_count") ON "recurring_lesson_series" TO v_scheduling_runtime;
GRANT UPDATE("kind","branch_id","teacher_id","enrollment_id","student_id","vehicle_id","group_id","group_membership_revision","starts_at","ends_at","actual_start","actual_end","status","revision","series_id","source_candidate_id","category_code") ON "lesson" TO v_scheduling_runtime;
GRANT UPDATE("student_id","membership_revision") ON "lesson_participant" TO v_scheduling_runtime;
GRANT UPDATE("operation_id","lesson_id","assessment_appointment_id","resource_kind","resource_key","starts_at","ends_at","status","released_at") ON "reservation_claim" TO v_scheduling_runtime;
GRANT UPDATE("kind","enrollment_id","student_id","assessment_definition_id","outstanding_requirement_id","reason","teacher_id","vehicle_id","branch_id","category_code","starts_at","ends_at","status") ON "assessment_appointment" TO v_scheduling_runtime;
GRANT UPDATE(status,finished_at,result_lesson_id,result_appointment_id,outcome_code) ON scheduling_operation TO v_scheduling_runtime;
DO $secure$ DECLARE f record; BEGIN
 FOR f IN SELECT p.oid::regprocedure AS signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f' AND NOT EXISTS(SELECT 1 FROM pg_depend dep WHERE dep.classid='pg_proc'::regclass AND dep.objid=p.oid AND dep.deptype='e') LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,public,pg_temp',f.signature);
 END LOOP;
END $secure$;
ALTER TABLE "scheduling_request" ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON "scheduling_request" TO v_scheduling_runtime USING (school_id=nullif(current_setting('vairas.school_id',true),'')::uuid) WITH CHECK (school_id=nullif(current_setting('vairas.school_id',true),'')::uuid);
ALTER TABLE "scheduling_request_enrollment" ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON "scheduling_request_enrollment" TO v_scheduling_runtime USING (EXISTS(SELECT 1 FROM "scheduling_request" p WHERE p."id"="scheduling_request_enrollment"."request_id" AND p."revision"="scheduling_request_enrollment"."request_revision" AND p.school_id=nullif(current_setting('vairas.school_id',true),'')::uuid)) WITH CHECK (EXISTS(SELECT 1 FROM "scheduling_request" p WHERE p."id"="scheduling_request_enrollment"."request_id" AND p."revision"="scheduling_request_enrollment"."request_revision" AND p.school_id=nullif(current_setting('vairas.school_id',true),'')::uuid));
