GRANT USAGE ON SCHEMA public TO v_scheduling_reservation_authority;
DO $$ BEGIN EXECUTE format('GRANT CONNECT ON DATABASE %I TO v_scheduling_reservation_authority',current_database()); END $$;
GRANT SELECT(resource_kind,resource_key,starts_at,ends_at,status) ON reservation_claim TO v_scheduling_reservation_authority;
CREATE POLICY reservation_internal ON reservation_claim FOR SELECT TO v_scheduling_reservation_authority USING(true);
GRANT SELECT(student_id,kind,starts_at,ends_at,status) ON lesson TO v_scheduling_reservation_authority;
CREATE POLICY reservation_internal ON lesson FOR SELECT TO v_scheduling_reservation_authority USING(true);
GRANT SELECT(student_id,kind,starts_at,ends_at,status) ON assessment_appointment TO v_scheduling_reservation_authority;
